import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Обзор пяти типов симбиотических цивилизаций","description":"","frontmatter":{},"headers":[],"relativePath":"ru/30-五种共生文明分型总览.md","filePath":"ru/30-五种共生文明分型总览.md","lastUpdated":1789183869000}'),i={name:"ru/30-五种共生文明分型总览.md"};function l(o,t,h,n,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="обзор-пяти-типов-симбиотических-цивилизации" tabindex="-1">Обзор пяти типов симбиотических цивилизаций <a class="header-anchor" href="#обзор-пяти-типов-симбиотических-цивилизации" aria-label="Permalink to &quot;Обзор пяти типов симбиотических цивилизаций&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>30</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Тип цивилизации, Пять моделей, Реальность как основа, Законо-сообразное обновление, Учёт местных условий</td></tr></tbody></table><h2 id="i-предпосылки-и-принципы-типов-цивилизации" tabindex="-1">I. Предпосылки и принципы типов цивилизаций <a class="header-anchor" href="#i-предпосылки-и-принципы-типов-цивилизации" aria-label="Permalink to &quot;I. Предпосылки и принципы типов цивилизаций&quot;">​</a></h2><p>При создании социальных систем Симбиотическая Цивилизация Якоря столкнулась с центральным вопросом: исторические традиции, культурный фон, ресурсные возможности и стадии развития планов и планет Вселенной безмерно различны — существует ли единая социальная система, «пригодная везде»? Ответ — нет. Один из центральных принципов — «само-рост»: каждая цивилизация должна выбирать путь по своим реальным условиям, а не по принудительной единой модели.</p><p>Поэтому в единой рамке «Симбиотической Конституции» цивилизация позволяет и поощряет разные регионы развивать разные формы. Долгой практикой выделены пять типов: Восточноазиатский интенсивный, Североевропейский социальный, Североамериканский плюралистический, Континентально-европейский социальный, Догоняющий развивающийся.</p><p>Принцип «реальность как основа, законо-сообразное обновление»:</p><ol><li><strong>Реальность как основа</strong>: все пять типов основаны на реальных моделях мира, извлекая ядро черт и преимущества институтов, а не выдуманы</li><li><strong>Законо-сообразное обновление</strong>: на базе реальных моделей, с законами культивации Хэн Юаньчжоу и симбиотическими идеями, институты обновляются и пересоздаются под нужды цивилизации</li><li><strong>Гармония в различии</strong>: модели различны, но все следуют основам Конституции — равные члены семьи</li><li><strong>Динамическая эволюция</strong>: типы не неизменны; каждая цивилизация корректирует, оптимизирует, вбирает преимущества других</li></ol><h2 id="ii-сравнение-ядра-черт-пяти-типов" tabindex="-1">II. Сравнение ядра черт пяти типов <a class="header-anchor" href="#ii-сравнение-ядра-черт-пяти-типов" aria-label="Permalink to &quot;II. Сравнение ядра черт пяти типов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Измерение</th><th>Восточноазиатский</th><th>Североевропейский</th><th>Североамериканский</th><th>Континентально-европейский</th><th>Догоняющий</th></tr></thead><tbody><tr><td>Ядро идеи</td><td>Приоритет коллектива, интенсивность</td><td>Высокая соцзащита, равенство, счастье</td><td>Свобода, плюрализм, равенство шансов</td><td>Социальный рынок, соучастие труда и капитала</td><td>Догоняющий прорыв</td></tr><tr><td>Распределение</td><td>Коллективная координация, по труду</td><td>Высокие налоги, трансферты</td><td>Рынок + соцстраховка</td><td>Рынок + социальная двойная колея</td><td>Стратегическая концентрация</td></tr><tr><td>Культивация</td><td>Массовая стандартизация</td><td>Всеобщая поддержка</td><td>Свободный выбор, конкурс</td><td>Двойная колея, школа-предприятие</td><td>Элита ведёт, всеобщее</td></tr><tr><td>Структура</td><td>Сильное государство, коллектив</td><td>Сильная защита, слабые классы</td><td>Слабое государство, сильное общество</td><td>Среднее государство, сильные союзы</td><td>Сильное государство, быстрая мобильность</td></tr><tr><td>Преимущество</td><td>Эффективность, исполнение</td><td>Счастье, равенство</td><td>Инновации, энергия</td><td>Стабильность, сплочённость</td><td>Быстрое развитие, прорыв</td></tr><tr><td>Вызов</td><td>Мало пространства личности</td><td>Слабая инновация</td><td>Большой разрыв богатства</td><td>Низкая админэффективность</td><td>Слабая база, дисбаланс</td></tr></tbody></table><h2 id="iii-детальное-позиционирование-пяти-типов" tabindex="-1">III. Детальное позиционирование пяти типов <a class="header-anchor" href="#iii-детальное-позиционирование-пяти-типов" aria-label="Permalink to &quot;III. Детальное позиционирование пяти типов&quot;">​</a></h2><h3 id="_3-1-восточноазиатскии-интенсивныи" tabindex="-1">3.1 Восточноазиатский интенсивный <a class="header-anchor" href="#_3-1-восточноазиатскии-интенсивныи" aria-label="Permalink to &quot;3.1 Восточноазиатский интенсивный&quot;">​</a></h3><p>Основан на моделях Восточной Азии реального мира; ядро — «приоритет коллектива, интенсивная эффективность». Коллективное выше индивидуального; сильная координация даёт эффективное распределение и масштабное развитие.</p><p>В культивации — массовая стандартизированная подготовка кадров; подряд, связанный с результатом, тяготеет к «коллективному подряду»: ресурсы берут семья, секта, община, внутри — вторичное распределение.</p><p>Преимущества: исполнение, эффективность, концентрация на большом деле. Вызов: пространство личности; баланс коллективного и свободного.</p><h3 id="_3-2-североевропеискии-социальныи" tabindex="-1">3.2 Североевропейский социальный <a class="header-anchor" href="#_3-2-североевропеискии-социальныи" aria-label="Permalink to &quot;3.2 Североевропейский социальный&quot;">​</a></h3><p>Основан на моделях скандинавских стран; ядро — «высокая соцзащита, равенство, счастье». Высокие налоги и трансферты — сбалансированное распределение богатства, защита «от колыбели до могилы».</p><p>В культивации — всеобщая защита: каждому достаточно базовых ресурсов и индивидуальная поддержка. Подряд тяготеет к «высоко-защитному»: выше норма базовых полей, высокая доля излишка в общественный фонд.</p><p>Преимущества: счастье, равенство, мало конфликтов. Вызов: слабая инновация; баланс защиты и стимула.</p><h3 id="_3-3-североамериканскии-плюралистическии" tabindex="-1">3.3 Североамериканский плюралистический <a class="header-anchor" href="#_3-3-североамериканскии-плюралистическии" aria-label="Permalink to &quot;3.3 Североамериканский плюралистический&quot;">​</a></h3><p>Основан на моделях Северной Америки; ядро — «свобода, плюрализм, равенство шансов». Свобода личности и рыночная конкуренция дают оптимум ресурсов и максимум ценности личности.</p><p>В культивации — свободный выбор, конкурс; ресурсы через конкуренцию. Подряд — «рыночный»: распределение связано с рыночным результатом, публичная защита — «страховочная сеть».</p><p>Преимущества: инновации, энергия, притяжение талантов. Вызов: разрыв богатства; баланс конкуренции и справедливости.</p><h3 id="_3-4-континентально-европеискии-социальныи" tabindex="-1">3.4 Континентально-европейский социальный <a class="header-anchor" href="#_3-4-континентально-европеискии-социальныи" aria-label="Permalink to &quot;3.4 Континентально-европейский социальный&quot;">​</a></h3><p>Основан на моделях континентальной Европы; ядро — «социальный рынок, соучастие труда и капитала». Баланс рыночной эффективности и социальной справедливости; рынок плюс социальная политика.</p><p>В культивации — двойная колея: рыночные институты и социальная защита дополняют друг друга. Подряд — «социальное партнёрство»: культиваторы, наставники, управление совместно решают распределение.</p><p>Преимущества: стабильность, сплочённость, гармония труда и капитала. Вызов: админэффективность; баланс консенсуса и решений.</p><h3 id="_3-5-догоняющии-развивающиися" tabindex="-1">3.5 Догоняющий развивающийся <a class="header-anchor" href="#_3-5-догоняющии-развивающиися" aria-label="Permalink to &quot;3.5 Догоняющий развивающийся&quot;">​</a></h3><p>Основан на моделях развивающихся стран; ядро — «догоняющий прорыв, концентрация». Для слабой базы и дефицита ресурсов: концентрация на ключевых областях, точка ведёт целое.</p><p>В культивации — «элита ведёт, всеобщее»: сначала элита, затем она поднимает всех. Подряд — «стратегический»: ресурсы к стратегическим областям и высокому потенциалу, градиентное продвижение.</p><p>Преимущества: скорость, прорыв, прыжок в развитии. Вызов: слабая база, дисбаланс; баланс прорыва и полноты.</p><h2 id="iv-связи-и-взаимообучение-пяти-типов" tabindex="-1">IV. Связи и взаимообучение пяти типов <a class="header-anchor" href="#iv-связи-и-взаимообучение-пяти-типов" aria-label="Permalink to &quot;IV. Связи и взаимообучение пяти типов&quot;">​</a></h2><p>Не изолированы и не противопоставлены — равные члены семьи, широкий обмен:</p><ol><li><strong>Институциональное взаимообучение</strong>: например, восточноазиатский учится соцзащите североевропейского; североамериканский — механизму труда и капитала континентального</li><li><strong>Поток талантов</strong>: культиваторы свободно текут между типами</li><li><strong>Взаимодополнение ресурсов</strong>: по сравнительным преимуществам</li><li><strong>Совместное управление</strong>: межрегиональные и межплановые дела — через консультации</li></ol><p>Цель не «схождение типов», а «каждый хорош по-своему, красота общая»: каждый тип идёт своим путём, уважая, учась, двигаясь вместе.</p><h2 id="v-выбор-и-переход-типов" tabindex="-1">V. Выбор и переход типов <a class="header-anchor" href="#v-выбор-и-переход-типов" aria-label="Permalink to &quot;V. Выбор и переход типов&quot;">​</a></h2><p>Выбор типа не навязан извне: исторические традиции, культура, ресурсы, стадия. Механизм «оценки и ориентации типов цивилизаций» помогает регионам.</p><p>Тип не пожизнен: с изменением условий регион переходит из типа в тип или образует «гибрид». Цивилизация даёт полную поддержку, плавный переход.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Пять типов — воплощение мудрости «гармонии в различии». Единые принципы Конституции и уважение разнообразия; реальные модели и законы космоса. Каждый тип силён по-своему; учатся, дополняют, идут вместе в семье цивилизации — великий поток совместного прогресса Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>31-东亚集约型文明 (Восточноазиатская интенсивная цивилизация)</li><li>32-北欧福利型文明 (Североевропейская социальная цивилизация)</li><li>33-北美多元型文明 (Североамериканская плюралистическая цивилизация)</li></ul>',41)])])}const b=a(i,[["render",l]]);export{c as __pageData,b as default};
